//! Shared EntityTx bytes generated by TypeScript's canonical storage codec.

use std::collections::BTreeSet;
use std::path::Path;

use xln_rscore_entity_kernel::{ENTITY_TX_TYPES, EntityTxKind};
use xln_rscore_runtime::{
    RuntimeEntityInput, canonical_value_from_tagged_json, decode_storage_payload,
    encode_storage_payload,
};

const OWNER: &str = "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";

fn vectors() -> Vec<(String, Vec<u8>)> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../core/__tests__/rscore/entity-tx-wire-vectors.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    let rows = serde_json::from_str::<Vec<serde_json::Value>>(&text)
        .unwrap_or_else(|error| panic!("decode {}: {error}", path.display()));
    rows.into_iter()
        .map(|row| {
            let name = row
                .get("name")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_else(|| panic!("vector name in {row}"))
                .to_string();
            let hex = row
                .get("bytes")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_else(|| panic!("vector bytes for {name}"));
            let bytes = hex::decode(hex).unwrap_or_else(|error| panic!("{name}: hex: {error}"));
            (name, bytes)
        })
        .collect()
}

#[test]
fn every_typescript_entity_tx_decodes_and_reencodes_byte_identically() {
    let mut covered = BTreeSet::new();
    let mut admission_failures = Vec::new();
    let vectors = vectors();
    assert_eq!(
        vectors
            .iter()
            .map(|(name, _)| name.as_str())
            .collect::<Vec<_>>(),
        ENTITY_TX_TYPES,
        "shared vector order must equal the canonical TS/Rust catalog",
    );
    for (name, bytes) in vectors {
        let value = decode_storage_payload(&bytes)
            .unwrap_or_else(|error| panic!("{name}: decode: {error}"));
        let object = value
            .as_object()
            .unwrap_or_else(|| panic!("{name}: EntityTx object"));
        assert_eq!(object.len(), 2, "{name}: exact type/data fields");
        assert!(object.contains_key("data"), "{name}: data");
        let kind = object
            .get("type")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_else(|| panic!("{name}: type"));
        let parsed =
            EntityTxKind::parse(kind).unwrap_or_else(|error| panic!("{name}: catalog: {error}"));
        assert_eq!(parsed.as_str(), kind, "{name}: catalog round trip");
        assert!(covered.insert(kind.to_string()), "{name}: duplicate kind");

        // This is the production native EntityTx admission path, not a
        // discriminant-only parser. It projects protocol lanes and invokes
        // the typed local/Account decoders used by live Runtime execution.
        if let Err(error) = RuntimeEntityInput::decode(serde_json::json!({
            "entityId": OWNER,
            "signerId": "owner",
            "entityTxs": [value.clone()],
        })) {
            let detail = error.to_string();
            let expected_boundary_rejection = match name.as_str() {
                // These transactions are executable, but never as unsigned
                // raw EntityInput. Their production authority is the outer
                // EntityCommand or authenticated Runtime J observation.
                "propose" | "vote" | "j_event" => {
                    detail.starts_with("RUNTIME_ENTITY_TX_EXECUTION_UNSUPPORTED:")
                }
                // This vector deliberately places an ordinary action inside
                // EntityCommand; collective actions must first be proposed.
                // The shared vector carries a canonical placeholder signature
                // (low-s, recovery byte 1) so both command codecs reach this
                // exact rule instead of stopping at signature canonicality.
                "entityCommand" => {
                    detail.starts_with("ENTITY_COMMAND_COLLECTIVE_ACTION_REQUIRES_PROPOSAL:")
                }
                // The shared codec vector covers every optional field, while
                // canonical TS execution rejects these tokenless values too.
                "setHubConfig" => detail.contains("HUB_REBALANCE_TOKENLESS_RAW_OVERRIDE_FORBIDDEN"),
                _ => false,
            };
            if !expected_boundary_rejection {
                admission_failures.push(format!("{name}={error}"));
            }
        }

        let canonical = canonical_value_from_tagged_json(&value)
            .unwrap_or_else(|error| panic!("{name}: canonical value: {error}"));
        let encoded = encode_storage_payload(&canonical)
            .unwrap_or_else(|error| panic!("{name}: encode: {error}"));
        assert_eq!(encoded, bytes, "{name}: Rust changed TypeScript bytes");
    }

    assert_eq!(covered.len(), 63, "shared EntityTx vector cardinality");
    assert_eq!(
        covered,
        ENTITY_TX_TYPES.into_iter().map(str::to_string).collect(),
        "shared vectors must cover the complete Rust EntityTx catalog",
    );
    assert!(
        admission_failures.is_empty(),
        "production Rust EntityTx admission gaps:\n{}",
        admission_failures.join("\n"),
    );
}
